-- Rich PostgreSQL fixture used by spec/integration/postgresql_round_trip_spec.rb.
-- Every object here must survive: dump -> load into an empty database -> dump (byte-identical).

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TYPE order_status AS ENUM ('pending', 'it''s shipped', 'delivered');
ALTER TYPE order_status ADD VALUE 'cancelled' BEFORE 'delivered';
CREATE TYPE "MoodType" AS ENUM ('happy', 'sad');
CREATE TYPE address AS (street varchar(120), city text, zip char(5));
CREATE TYPE float_range AS RANGE (subtype = float8);

CREATE DOMAIN email AS text NOT NULL DEFAULT 'nobody@example.com'
  CONSTRAINT email_has_at CHECK (VALUE ~ '@')
  CONSTRAINT email_not_blank CHECK (VALUE <> '');
CREATE DOMAIN positive_int AS integer CHECK (VALUE > 0);

CREATE SEQUENCE invoice_number_seq START WITH 1000 INCREMENT BY 5 MINVALUE 1000 MAXVALUE 999999 CACHE 10 CYCLE;

CREATE TABLE "Users" (
  id bigint GENERATED ALWAYS AS IDENTITY (START WITH 100 INCREMENT BY 10),
  "Email" email,
  "select" text,
  first_name varchar(50) NOT NULL,
  last_name varchar(50) NOT NULL,
  full_name text GENERATED ALWAYS AS (first_name || ' ' || last_name) STORED,
  nickname text COLLATE "C",
  tags varchar(30)[] DEFAULT '{}'::varchar[],
  scores numeric(10,2)[],
  mood "MoodType",
  home address,
  created_at timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp(0) with time zone,
  CONSTRAINT users_primary PRIMARY KEY (id),
  CONSTRAINT users_email_unique UNIQUE ("Email"),
  CONSTRAINT users_names_check CHECK (first_name <> last_name)
);

CREATE TABLE accounts (
  id serial PRIMARY KEY,
  code text NOT NULL,
  region text NOT NULL,
  balance numeric(12,2) DEFAULT 0 NOT NULL,
  credits positive_int,
  CONSTRAINT accounts_code_region_key UNIQUE (code, region)
);
ALTER TABLE accounts ADD CONSTRAINT accounts_balance_check CHECK (balance >= 0) NOT VALID;

CREATE TABLE orders (
  id bigserial PRIMARY KEY,
  user_id bigint NOT NULL,
  account_code text,
  account_region text,
  status order_status NOT NULL DEFAULT 'pending',
  invoice_number integer DEFAULT nextval('invoice_number_seq'),
  total numeric(10,2),
  note text,
  CONSTRAINT orders_user_fk FOREIGN KEY (user_id) REFERENCES "Users"(id) ON DELETE CASCADE ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT orders_account_fk FOREIGN KEY (account_code, account_region) REFERENCES accounts(code, region) MATCH FULL ON DELETE SET NULL
);

CREATE TABLE room_bookings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  room integer NOT NULL,
  during tsrange NOT NULL,
  CONSTRAINT no_double_booking EXCLUDE USING gist (room WITH =, during WITH &&)
);

CREATE TABLE line_items (
  order_id bigint NOT NULL,
  position integer NOT NULL,
  sku text NOT NULL,
  PRIMARY KEY (order_id, position)
);

ALTER TABLE line_items ADD CONSTRAINT line_items_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) NOT VALID;

CREATE INDEX index_orders_on_user_id_partial ON orders (user_id) WHERE status <> 'delivered';
CREATE INDEX index_users_on_lower_email ON "Users" (lower("Email"::text));
CREATE INDEX index_orders_covering ON orders (user_id) INCLUDE (total);
CREATE INDEX index_orders_desc ON orders (total DESC NULLS LAST, id);
CREATE UNIQUE INDEX index_line_items_sku ON line_items (sku);
CREATE INDEX "Index_Users_Mixed" ON "Users" (last_name);

-- Partitioned table with range partitions and a partitioned index
CREATE TABLE events (
  id bigint NOT NULL,
  occurred_at date NOT NULL,
  payload jsonb,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE events_2024 PARTITION OF events FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE events_2025 PARTITION OF events FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
CREATE TABLE events_default PARTITION OF events DEFAULT;
CREATE INDEX index_events_on_payload ON events USING gin (payload);

-- Functions: overloads, SECURITY DEFINER, SET search_path, volatility, procedure
CREATE FUNCTION add_numbers(a integer, b integer) RETURNS integer
  LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT a + b $$;
CREATE FUNCTION add_numbers(a numeric, b numeric) RETURNS numeric
  LANGUAGE sql IMMUTABLE AS $$ SELECT a + b $$;
CREATE FUNCTION secure_now() RETURNS timestamptz
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog
  AS $$ BEGIN RETURN now(); END $$;
CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END
$$;
CREATE FUNCTION audit_statement() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RETURN NULL;
END
$$;
CREATE PROCEDURE reset_scores(p_user bigint) LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE 'reset %', p_user;
END
$$;

CREATE TRIGGER users_touch BEFORE UPDATE ON "Users"
  FOR EACH ROW WHEN (OLD.last_name IS DISTINCT FROM NEW.last_name) EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER orders_audit AFTER INSERT OR DELETE ON orders
  FOR EACH STATEMENT EXECUTE FUNCTION audit_statement();
CREATE CONSTRAINT TRIGGER line_items_check AFTER INSERT ON line_items
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION audit_statement();
CREATE TRIGGER events_audit AFTER INSERT ON events
  FOR EACH ROW EXECUTE FUNCTION audit_statement();

-- Views depending on views (names chosen so alphabetical order is wrong)
CREATE VIEW b_active_users AS SELECT id, "Email", first_name FROM "Users" WHERE "select" IS NULL;
CREATE VIEW a_active_user_emails AS SELECT "Email" FROM b_active_users;
CREATE MATERIALIZED VIEW order_totals AS
  SELECT user_id, sum(total) AS total FROM orders GROUP BY user_id;
CREATE UNIQUE INDEX index_order_totals_on_user_id ON order_totals (user_id);

-- Functions whose bodies or signatures need relations (alphabetical order and
-- "all functions before tables" are both wrong for these)
CREATE FUNCTION count_orders() RETURNS bigint
  LANGUAGE sql STABLE AS $$ SELECT count(*) FROM orders $$;
CREATE FUNCTION pending_orders() RETURNS SETOF orders
  LANGUAGE sql STABLE AS $$ SELECT * FROM orders WHERE status = 'pending' $$;
CREATE FUNCTION order_label(o orders) RETURNS text
  LANGUAGE sql IMMUTABLE AS $$ SELECT o.id::text $$;
CREATE FUNCTION order_batch_size(batch orders[]) RETURNS integer
  LANGUAGE sql IMMUTABLE AS $$ SELECT cardinality(batch) $$;
CREATE FUNCTION atomic_order_count() RETURNS bigint
  LANGUAGE sql STABLE BEGIN ATOMIC SELECT count(*) FROM orders; END;
CREATE FUNCTION b_double(x integer) RETURNS integer
  LANGUAGE sql IMMUTABLE AS $$ SELECT x * 2 $$;
CREATE FUNCTION a_quadruple(x integer) RETURNS integer
  LANGUAGE sql IMMUTABLE BEGIN ATOMIC SELECT b_double(b_double(x)); END;

-- Views, materialized views and functions that depend on each other
CREATE VIEW a_pending_order_labels AS SELECT order_label(p.*) AS label FROM pending_orders() p;
CREATE VIEW big_spenders AS SELECT user_id FROM order_totals WHERE total > 100;
CREATE MATERIALIZED VIEW a_big_spender_count AS SELECT count(*) AS spenders FROM big_spenders;
CREATE MATERIALIZED VIEW active_user_count AS SELECT count(*) AS users FROM b_active_users;
CREATE FUNCTION a_list_big_spenders() RETURNS SETOF big_spenders
  LANGUAGE sql STABLE AS $$ SELECT * FROM big_spenders $$;
CREATE VIEW a_spender_ids AS SELECT user_id FROM a_list_big_spenders();

COMMENT ON FUNCTION pending_orders() IS 'Orders still pending';
COMMENT ON TABLE "Users" IS 'People who log in';
COMMENT ON COLUMN "Users"."Email" IS 'Login e-mail, it''s unique';
COMMENT ON INDEX index_orders_covering IS 'Covering index';
COMMENT ON VIEW b_active_users IS 'Active users';
COMMENT ON MATERIALIZED VIEW order_totals IS 'Totals per user';
COMMENT ON FUNCTION add_numbers(integer, integer) IS 'Adds integers';
COMMENT ON FUNCTION add_numbers(numeric, numeric) IS 'Adds numerics';
COMMENT ON TABLE events IS 'Partitioned events';

-- Types that depend on later-named types, and a domain whose CHECK calls a function
CREATE TYPE z_kind AS ENUM ('x', 'y');
CREATE TYPE a_pair AS (kind z_kind, n integer);
CREATE DOMAIN b_contact_email AS text CHECK (VALUE ~ '@');
CREATE TYPE a_contact AS (addr b_contact_email, kinds z_kind[]);
CREATE FUNCTION z_is_even(i integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT i % 2 = 0 $$;
CREATE DOMAIN a_even_int AS integer CHECK (z_is_even(VALUE));
CREATE FUNCTION a_double_even(v a_even_int) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT v * 2 $$;
CREATE TABLE contacts (id bigserial PRIMARY KEY, pair a_pair, contact a_contact, even a_even_int);

-- A function whose body uses a standalone sequence
CREATE SEQUENCE ticket_seq;
CREATE FUNCTION a_next_ticket() RETURNS bigint LANGUAGE sql BEGIN ATOMIC SELECT nextval('ticket_seq'); END;

-- Identifiers containing commas and dots
CREATE TABLE "a,b" ("x,y" integer, z integer, PRIMARY KEY ("x,y", z), CONSTRAINT "a,b_uniq" UNIQUE (z, "x,y"));
CREATE TABLE "a.b" (id integer PRIMARY KEY, "c.d" integer);
COMMENT ON COLUMN "a.b"."c.d" IS 'dotted column';

-- Unlogged tables, storage parameters and table inheritance
CREATE UNLOGGED TABLE scratch (id integer);
CREATE TABLE tuned (id integer) WITH (fillfactor=70, autovacuum_enabled=false);
CREATE TABLE z_vehicles (id integer NOT NULL, name text DEFAULT 'unnamed', CONSTRAINT z_vehicles_id_positive CHECK (id > 0));
CREATE TABLE y_wheeled (wheels integer NOT NULL DEFAULT 4);
CREATE TABLE b_cars (doors integer, name text) INHERITS (z_vehicles, y_wheeled);
CREATE TABLE a_sports_cars (top_speed integer) INHERITS (b_cars);

COMMENT ON PROCEDURE reset_scores(bigint) IS 'Resets scores';
